nodes=0

def select_vertex():
    # max saturation, then degree
    return max(uncolored, key=lambda v: (len({colors[u] for u in adj[v] if colors[u]!=-1}), deg[v]))

def order_colors(v):
    forbidden={colors[u] for u in adj[v] if colors[u]!=-1}
    return [c for c in range(4) if c not in forbidden]

def feasible_uncolored_check():
    for v in uncolored:
        forbidden={colors[u] for u in adj[v] if colors[u]!=-1}
        if len(forbidden)==4:
            return False
    return True

def bt():
    global nodes
    nodes+=1
    if not uncolored:
        return True
    v=select_vertex()
    opts=order_colors(v)
    # try least used maybe
    # counts = [colors.count(c) for c in range(4)]
    # opts.sort(key=lambda c: counts[c])
    if not opts: return False
    uncolored.remove(v)
    for c in opts:
        colors[v]=c
        # forward check
        ok=True
        for w in adj[v]:
            if w in uncolored:
                forb={colors[u] for u in adj[w] if colors[u]!=-1}
                if len(forb)==4:
                    ok=False; break
        if ok and bt():
            return True
        colors[v]=-1
    uncolored.add(v)
    return False

